const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

const token = 'TU_TOKEN_DISCORD'; // Reemplaza por tu token de Discord

client.once('ready', () => {
  console.log('Bot listo');
});

client.on('messageCreate', async message => {
  if (message.content.startsWith('~/ban')) {
    if (!message.member.permissions.has('BAN_MEMBERS')) {
      return message.reply('No tienes permisos para banear a los miembros.');
    }

    const user = message.mentions.users.first();
    if (!user) {
      return message.reply('Debes mencionar a un usuario válido.');
    }

    const member = message.guild.members.cache.get(user.id);
    if (!member) {
      return message.reply('Este usuario no está en el servidor.');
    }

    try {
      await member.ban({ days: 0, reason: 'Command execution' });
      await message.reply(`Usuario ${user.tag} banido con éxito.`);
    } catch (error) {
      console.error(error);
      await message.reply('Ocurrió un error al intentar banear al usuario.');
    }
  }
});

client.login(token);
```

